-- The record of the auth store's migrations.
create table "auth_migrations" (
  "version" integer primary key,
  "name" text not null,
  "applied_at" timestamptz default current_timestamp not null
);

-- auth 1 core: Better Auth's users, sessions, accounts, verifications and signing keys.
create table if not exists "user" (id text primary key);

alter table "user"
  add column if not exists "name" text not null,
  add column if not exists "email" text not null unique,
  add column if not exists "email_verified" boolean not null,
  add column if not exists "image" text,
  add column if not exists "created_at" timestamptz default current_timestamp not null,
  add column if not exists "updated_at" timestamptz default current_timestamp not null,
  add column if not exists "role" text,
  add column if not exists "banned" boolean,
  add column if not exists "ban_reason" text,
  add column if not exists "ban_expires" timestamptz,
  add column if not exists "last_role" text,
  add column if not exists "email_confirmed_at" timestamptz;

create table "session" (
  id text primary key,
  "expires_at" timestamptz not null,
  "token" text not null unique,
  "created_at" timestamptz default current_timestamp not null,
  "updated_at" timestamptz not null,
  "ip_address" text,
  "user_agent" text,
  "user_id" text not null references "user" (id) on delete cascade,
  "impersonated_by" text,
  "active_role" text
);

create index "session_user_id_idx" on "session" ("user_id");

create table "account" (
  id text primary key,
  "account_id" text not null,
  "provider_id" text not null,
  "user_id" text not null references "user" (id) on delete cascade,
  "access_token" text,
  "refresh_token" text,
  "id_token" text,
  "access_token_expires_at" timestamptz,
  "refresh_token_expires_at" timestamptz,
  "scope" text,
  "password" text,
  "created_at" timestamptz default current_timestamp not null,
  "updated_at" timestamptz not null
);

create index "account_user_id_idx" on "account" ("user_id");

create table "verification" (
  id text primary key,
  "identifier" text not null,
  "value" text not null,
  "expires_at" timestamptz not null,
  "created_at" timestamptz default current_timestamp not null,
  "updated_at" timestamptz default current_timestamp not null
);

create index "verification_identifier_idx" on "verification" ("identifier");

create table "jwks" (
  id text primary key,
  "public_key" text not null,
  "private_key" text not null,
  "created_at" timestamptz not null,
  "expires_at" timestamptz,
  "alg" text,
  "crv" text
);

insert into "auth_migrations" ("version", "name") values (1, 'core');

-- auth 2 account_keys: One account per provider and account id, and per person where a provider links one.
do $check$
declare
  found text;
begin
  select string_agg(format('%s %s (accounts %s)', provider, subject, ids), '; ') into found
  from (
    select "provider_id" as provider, "account_id" as subject, string_agg(id::text, ', ' order by id) as ids
    from "account" group by "provider_id", "account_id" having count(*) > 1 order by 1, 2 limit 20
  ) as twice;
  if found is not null then
    raise exception 'The auth store has more than one account for a provider and account id: %. Keep one of each in a migration of the project''s own written before this one, then apply again.', found;
  end if;
end
$check$;

create unique index "account_provider_id_account_id_uidx" on "account" ("provider_id", "account_id");

alter table "account" add column "single_subject_user_id" text;

create unique index "account_provider_id_single_subject_user_id_uidx" on "account" ("provider_id", "single_subject_user_id");

-- auth 3 user_indexes: The indexes that find the active admins and page through the users.
create index if not exists "user_active_admin_idx" on "user" (id) where "banned" is not true and 'admin' = any(regexp_split_to_array(regexp_replace(regexp_replace(coalesce("role", 'user'), '^\s*\{(.*)\}\s*$', '\1'), '^\s*"?|"?\s*$', '', 'g'), '"?\s*,\s*"?'));

create index if not exists "user_created_at_id_idx" on "user" ("created_at", id);

insert into "auth_migrations" ("version", "name") values (12, 'user_indexes');

-- auth 4 verification_pattern_index: The index that finds app invitations.
create index "verification_identifier_pattern_idx" on "verification" ("identifier" text_pattern_ops);

-- auth 5 user_name_search: The indexes that find the users by a part of their name and list them by name.
create extension if not exists pg_trgm;

create index if not exists "user_name_id_idx" on "user" ("name", id);

create index if not exists "user_name_trgm_idx" on "user" using gin ("name" gin_trgm_ops);

insert into "auth_migrations" ("version", "name") values (14, 'user_name_search');

