alter table "mail_sender" add column "provider_state_read_at" timestamptz;

alter table "mail_sender" add column "removed_at" timestamptz;

update "mail_sender" set "typed_at" = "created_at";

update "mail_sender" set "connection_id" = only_one.id
from (
  select "user_id" as user_id, (array_agg(id))[1] as id from "account"
  where "provider_id" = 'google' and 'https://www.googleapis.com/auth/gmail.send' = any(regexp_split_to_array(coalesce("scope", ''), '[\s,]+'))
  group by "user_id" having count(*) = 1
) as only_one
where "mail_sender"."user_id" = only_one.user_id;

create unique index "mail_sender_connection_address_uidx" on "mail_sender" ("connection_id", "address_key");

create index "mail_sender_user_address_idx" on "mail_sender" ("user_id", "address_key");

do $drop$
declare
  found text;
begin
  select con.conname into found from pg_constraint con
  where con.conrelid = '"mail_sender"'::regclass and con.contype = 'u'
    and (select array_agg('"' || att.attname || '"' order by att.attname) from pg_attribute att where att.attrelid = con.conrelid and att.attnum = any(con.conkey))
      = (select array_agg(name order by name) from unnest(array['"user_id"', '"address"']) as name);
  if found is not null then
    execute format('alter table %s drop constraint %I', '"mail_sender"'::regclass, found);
  end if;
end
$drop$;

